mapper.select:
SELECT uuid, external_id
FROM evaluation_datasets
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL
FOR UPDATE

SELECT CAST(COALESCE(MAX(position), 0) AS integer)
FROM evaluation_cases
WHERE version_uuid = #{versionUUID}

SELECT

FROM evaluation_datasets d
JOIN evaluation_dataset_versions v ON v.dataset_uuid = d.uuid
WHERE d.organization_uuid = #{organizationUUID}
AND d.workspace_uuid = #{workspaceUUID}
AND d.external_id = #{externalID}
AND d.deleted_at IS NULL
AND v.version = (
    SELECT MAX(version)
    FROM evaluation_dataset_versions
    WHERE dataset_uuid = d.uuid
)

SELECT

FROM evaluation_datasets d
JOIN evaluation_dataset_versions v ON v.dataset_uuid = d.uuid
WHERE d.organization_uuid = #{params.OrganizationUUID}
AND d.workspace_uuid = #{params.WorkspaceUUID}
AND d.deleted_at IS NULL
AND v.version = (
    SELECT MAX(version)
    FROM evaluation_dataset_versions
    WHERE dataset_uuid = d.uuid
)
ORDER BY d.created_at DESC, d.uuid DESC
LIMIT #{params.Limit} OFFSET #{params.Offset}

mapper.update:
UPDATE evaluation_datasets
SET deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL

mapper.select:
SELECT

