ORDER BY position ASC

mapper.update:
UPDATE evaluation_cases
SET query = #{params.Query},
    expected_answer = #{params.ExpectedAnswer},
    expected_tool_trace = CAST(#{params.ExpectedToolTrace} AS jsonb),
    source_session_id = #{params.SourceSessionID},
    polarity = #{params.Polarity},
    acceptance = #{params.Acceptance},
    updated_at = #{params.UpdatedAt}
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND dataset_uuid = #{params.DatasetUUID}
AND external_id = #{params.ExternalID}
AND deleted_at IS NULL
RETURNING

UPDATE evaluation_cases
SET deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND dataset_uuid = #{datasetUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL
